"// hooks/dashboard.ts",
"var GLYPH = {",
"  done: \"✓\",",
"  doing: \"▸\",",
"  todo: \"•\",",
"  waiting: \"●\",",
"  running: \"◐\",",
"  blocked: \"!\",",
"  cancelled: \"–\"",
"};",
"var LEGEND = [\"done\", \"doing\", \"todo\", \"waiting\", \"running\", \"blocked\", \"cancelled\"];",
"var esc2 = (text) => text.replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\");",
"var htmlLang = (s) => s.lang === \"en\" ? \"en\" : s.lang === \"zh-CN\" ? \"zh-Hans\" : \"zh-Hant\";",
"var steps = (list) => `<ol class=\"steps\">${list.map((step) => `<li class=\"${step.isCurrent ? \"now\" : \"\"}\"><span class=\"n\">${step.number ?? \"\"}</span>` + `<span class=\"g\" style=\"color:var(--${roleOf(step.status)})\">${GLYPH[step.status]}</span>` + `<span class=\"t${step.status === \"done\" || step.status === \"cancelled\" ? \" quiet\" : \"\"}\">${esc2(step.text)}</span>` + (step.note === \"\" ? \"\" : `<span class=\"note\" style=\"color:var(--${roleOf(step.status)})\">${esc2(step.note)}</span>`) + \"</li>\").join(\"\")}</ol>`;",
"var textRole = (role) => role === \"waiting\" ? \"waiting-text\" : role;",
"var roleOf = (status) => textRole(stepRole(status));",
"var toneVar = (tone) => textRole(toneRole(tone));",
"var askVar = (kind) => textRole(askRole(kind));",
"var bar = (done, total) => {",
"  const percent = total === 0 ? 0 : Math.round(done / total * 100);",
"  return `<span class=\"bar\"><span style=\"width:${percent}%;background:var(--${done === total && total > 0 ? \"done\" : \"accent\"})\"></span></span>`;",
"};",
"var waitingItem = (item, s) => `<div class=\"ask\"><div><span class=\"chip\" style=\"color:var(--${askVar(item.kind)})\">${esc2(s.ask[item.kind])}</span>` + `<b>${esc2(item.text)}</b></div>` + `<div class=\"where\">${agentMark(item.agent, item.where === \"manual\")}${esc2(item.project)} › ${esc2(item.task)}${item.agent === \"\" ? \"\" : ` · ${esc2(item.agent)}`}</div>` + (item.note === \"\" ? item.context === \"\" ? \"\" : `<div class=\"quiet\">${esc2(s.contextLine(item.context))}</div>` : `<div>${esc2(item.note)}</div>`) + (item.command === null || item.kind !== \"do\" ? \"\" : `<code>${esc2(item.command)}</code>`) + (item.link === null ? \"\" : `<a href=\"${esc2(item.link)}\">${esc2(s.openLink)}</a>`) + `<div class=\"quiet\">${esc2(item.where === \"manual\" ? \"\" : s.replyElsewhere(item.task, \"\", item.agent))}${item.when === \"\" ? \"\" : ` · ${esc2(item.when)}`}</div>` + \"</div>\";",
"var row = (it, s, showProject) => {",
"  const meta = [it.due === null ? \"\" : it.due.date, showProject ? it.project : \"\", it.agent, it.status, it.pr, it.when].filter((part) => part !== \"\");",
"  return `<details class=\"row\" data-key=\"${esc2(it.key)}\"><summary><span class=\"title\">${esc2(it.title)}</span>` + `<span class=\"tail\" style=\"color:var(--${it.due === null ? \"muted\" : toneVar(it.due.tone)})\">${esc2(it.due === null ? `${it.done}/${it.total}` : it.due.left)}</span>` + `<span class=\"meta\" style=\"color:var(--${toneVar(it.tone)})\">${agentMark(it.agent, it.auto === null)}${bar(it.done, it.total)} ${esc2(meta.join(\" · \"))}</span></summary>` + (it.runs === undefined ? \"\" : `<p class=\"quiet\">${esc2(it.runs)}</p>`) + (it.context === \"\" ? \"\" : `<p class=\"quiet\">${esc2(s.contextLine(it.context))}</p>`) + steps(it.steps) + \"</details>\";",
"};",
"var focus = (it, s) => {",
"  if (it === null)",
"    return `<section class=\"focus calm\">${esc2(s.nothingForYou)}</section>`;",
"  const body = it.type === \"ask\" ? waitingItem(it.item, s) : `<div><b style=\"color:var(--alert)\">${esc2(it.type === \"due\" ? `⚑ ${it.row.due?.left ?? \"\"}` : s.stuckLead)}</b> <b>${esc2(it.row.title)}</b></div>` + `<div class=\"where\">${esc2(it.row.project)}</div><div>${esc2(it.row.status)}</div>`;",
"  return `<section class=\"focus\"><div class=\"label\">${esc2(s.mostNeeded)}</div>${body}</section>`;",
"};",
"var section = (id, title, count, tone, hint, body, isOpen) => count === 0 ? \"\" : `<details class=\"section\" data-key=\"section:${id}\"${isOpen ? \" open\" : \"\"}><summary><span class=\"title\">${esc2(title)}</span>` + `<span class=\"count\" style=\"color:var(--${textRole(tone)})\">${count}</span>${hint === \"\" ? \"\" : `<span class=\"quiet\">${esc2(hint)}</span>`}</summary>${body}</details>`;",
"var dashboardHtml = (view, s, path, stamp, pending = []) => {",
"  pending = view.hasPendingQuestions ? pending.filter((turn) => !turn.isQuestion) : pending;",
"  const { active, due, today } = view.overview;",
"  const waiting = view.overview.waiting + pending.filter((turn) => turn.isQuestion).length;",
"  const nearest = view.due[0];",
"  const counts = [",
"    [\"●\", waiting, s.countWaiting, \"waiting\"],",
"    [\"▸\", active, s.countActive, \"accent\"],",
"    [\"⚑\", due, s.countDue, \"soon\"],",
"    [\"✓\", today, s.countToday, \"done\"]",
"  ];",
"  const sections = [",
"    [\"inbox\", s.boardInbox, pending.length],",
"    [\"waiting\", s.sectionWaiting, view.waiting.length],",
"    [\"reminder\", s.sectionQuestionReminders, view.reminder?.length ?? 0],",
"    [\"older\", s.sectionOlderQuestions, view.older?.length ?? 0],",
"    [\"idle\", s.idleCount(view.idle.length), view.idle.length],",
"    [\"stopped\", s.viewStopped, view.stopped.length],",
"    [\"due\", s.sectionDue, view.due.length],",
"    [\"others\", s.sectionActive, view.active.length],",
"    [\"recent\", s.sectionRecent, view.recent.length]",
"  ];",
"  return `<!doctype html>",
"<html lang=\"${htmlLang(s)}\">",
