"<body>",
"<header class=\"head\" id=\"head\"><div class=\"wide topbar\"><div class=\"brand\">${boardMark}<h1>${esc2(s.paneTitle)}</h1><span class=\"meta\">${esc2(stamp)}</span></div>${themeSwitch(s)}</div></header>",
"<div class=\"wide dashboard-shell\"><nav class=\"dash-nav\" aria-label=\"${esc2(s.dashSections)}\"><h2>${esc2(s.dashSections)}</h2>${sections.filter(([, , count]) => count > 0).map(([id, title, count]) => `<button type=\"button\" data-section=\"dash-${id}\"><span>${esc2(title)}</span>${id === \"idle\" ? \"\" : `<span class=\"ct\">${count}</span>`}</button>`).join(\"\")}</nav>",
"<main>",
"${view.warning ? `<p role=\"status\" style=\"color:var(--alert)\">${esc2(view.warning)}</p>` : \"\"}",
