"${view.pruned ? `<p role=\"status\" class=\"quiet\">${esc2(view.pruned)}</p>` : \"\"}",
"<section class=\"counts\">${counts.map(([glyph, n, word, role]) => `<span><span style=\"color:var(--${n > 0 ? textRole(role) : \"muted\"})\">${glyph} ${n}</span> ${esc2(word)}</span>`).join(\"\")}</section>",
"${view.focus === null && pending.some((turn) => turn.isQuestion) ? \"\" : focus(view.focus, s)}",
"${section(\"inbox\", s.boardInbox, pending.length, \"accent\", \"\", `<p class=\"quiet\">${esc2(s.dashInboxHint)}</p>` + pending.map((turn) => `<div class=\"ask\"><div class=\"where\">${agentMark(turn.agent)}${esc2([turn.project, turn.agent].filter((part) => part !== \"\").join(\" · \"))}</div>` + `<div><span style=\"color:var(--${turn.isQuestion ? \"waiting-text\" : \"accent\"})\">${turn.isQuestion ? \"●\" : \"◐\"}</span> ${turn.isQuestion ? esc2(clip(turn.text, 200)) : \"\"}</div></div>`).join(\"\"), true)}",
"${section(\"waiting\", s.sectionWaiting, view.waiting.length, \"waiting\", \"\", view.waiting.map((item) => waitingItem(item, s)).join(\"\"), true)}",
"${(view.stoppedAsking ?? 0) > 0 ? `<p class=\"quiet\"><button type=\"button\" data-section=\"dash-older\">${esc2(s.stoppedAsking(view.stoppedAsking))}</button></p>` : \"\"}",
"${section(\"reminder\", s.sectionQuestionReminders, view.reminder?.length ?? 0, \"muted\", s.questionAgingHint, (view.reminder ?? []).map((item) => waitingItem(item, s)).join(\"\"), false)}",
"${section(\"older\", s.sectionOlderQuestions, view.older?.length ?? 0, \"muted\", s.questionAgingHint, (view.older ?? []).slice(0, OLDER_SHOWN).map((item) => waitingItem(item, s)).join(\"\") + ((view.older?.length ?? 0) > OLDER_SHOWN ? `<details class=\"more\" data-key=\"older:more\"><summary>${esc2(s.showAllQuestions(view.older.length))}</summary>${view.older.slice(OLDER_SHOWN).map((item) => waitingItem(item, s)).join(\"\")}</details>` : \"\"), false)}",
"${view.hidden.length === 0 ? \"\" : `<p class=\"quiet\">${esc2(s.hiddenCount(view.hidden.length))}</p>`}",
"${view.idle.length === 0 ? \"\" : `<details class=\"section\" data-key=\"section:idle\"><summary><span class=\"quiet\">${esc2(s.idleCount(view.idle.length))}</span></summary>${view.idle.map((it) => row(it, s, true)).join(\"\")}</details>`}",
"${view.stopped.length === 0 ? \"\" : `<details class=\"section\" data-key=\"section:stopped\"><summary><span class=\"quiet\">${esc2(s.stoppedCount(view.stopped.length))}</span></summary>${view.stopped.map((it) => row(it, s, true)).join(\"\")}</details>`}",
"${view.background === undefined ? \"\" : `<p class=\"quiet\">${esc2(view.background)}</p>`}",
"${section(\"due\", s.sectionDue, view.due.length, \"soon\", nearest === undefined ? \"\" : s.nearestDue(nearest.title, nearest.due?.left ?? \"\"), view.due.map((it) => row(it, s, true)).join(\"\"), false)}",
"${section(\"others\", s.sectionActive, view.active.length, \"accent\", view.groups.map((group) => group.project).join(s.listSep), view.groups.map((group) => `<div class=\"group\"><h3>${esc2(group.project)}<span>${esc2(group.summary)}</span></h3>${group.rows.map((it) => row(it, s, false)).join(\"\")}</div>`).join(\"\"), true)}",
"${section(\"recent\", s.sectionRecent, view.recent.length, \"done\", \"\", `<ul class=\"steps\">${view.recent.map((item) => `<li><span></span><span style=\"color:var(--done)\">✓</span><span class=\"quiet\">${esc2([item.project, item.title, item.when].filter((part) => part !== \"\").join(\" · \"))}${(item.questions ?? []).map((question) => `<br>${esc2([question.text, question.note].filter(Boolean).join(\" — \"))}`).join(\"\")}</span></li>`).join(\"\")}</ul>`, false)}",
"<footer><div class=\"legend\">${LEGEND.map((status, index) => `<span><span style=\"color:var(--${roleOf(status)})\">${GLYPH[status]}</span> ${esc2(s.legendWords[index] ?? status)}</span>`).join(\"\")}<span>${esc2(s.legendDue)}</span></div>",
"<div>${esc2(s.legendCleanup)}</div><div>${esc2(s.progressFileShown)}</div></footer>",
"${(view.health?.length ?? 0) === 0 ? \"\" : `<details class=\"section sec\" data-key=\"section:health\"><summary><span class=\"title quiet\">${esc2(s.sectionHealth)}</span><span class=\"count\" style=\"color:var(--muted)\">${view.health.length}</span></summary>${view.health.map((line) => `<p class=\"quiet\">${esc2(line)}</p>`).join(\"\")}</details>`}",
"</main></div>",
"<script>",
"(function () {",
"  var key = 'progress-open';",
"  var open = {};",
"  try { open = JSON.parse(localStorage.getItem(key) || '{}'); } catch (e) {}",
"  document.querySelectorAll('details[data-key]').forEach(function (el) {",
"    var id = el.getAttribute('data-key');",
"    if (id.indexOf('section:') === 0) el.id = 'dash-' + id.slice(8);",
"    if (id in open) el.open = open[id];",
"    el.addEventListener('toggle', function () {",
"      open[id] = el.open;",
"      try { localStorage.setItem(key, JSON.stringify(open)); } catch (e) {}",
"    });",
"  });",
"  document.querySelectorAll('button[data-section]').forEach(function (button) {",
"    button.addEventListener('click', function () {",
"      var section = document.getElementById(button.getAttribute('data-section'));",
"      if (section) { section.open = true; section.scrollIntoView({ block: 'start' }); }",
"    });",
"  });",
"  if (typeof ResizeObserver === 'function') {",
"    var head = document.getElementById('head');",
"    new ResizeObserver(function () { document.documentElement.style.setProperty('--head-h', head.offsetHeight + 'px'); }).observe(head);",
"  }",
"  try { var y = sessionStorage.getItem('progress-y'); if (y) window.scrollTo(0, +y); } catch (e) {}",
"  setTimeout(function () {",
"    try { sessionStorage.setItem('progress-y', String(window.scrollY)); } catch (e) {}",
"    location.reload();",
"  }, 30000);",
"})();",
"</script>",
"</body>",
"</html>",
