"// hooks/grouping.ts",
"var WORKING_MS = 30 * 60 * 1000;",
"var DONE_MS = 7 * 24 * 60 * 60 * 1000;",
"var MAX_HOPS2 = 8;",
"var ICONS = new Map(AGENT_ICONS.flatMap((icon) => [[icon.file, icon.file], [icon.file.split(\"-\")[0] ?? icon.file, icon.file]]));",
"var keyOf = (agent) => agent.trim().toLowerCase() || \"claude\";",
"var iconOf = (agent) => {",
"  const first = agent.split(/\\s+/)[0] ?? agent;",
"  return ICONS.get(first) ?? `letter:${(Array.from(first)[0] ?? \"?\").toUpperCase()}`;",
"};",
"var plain4 = (text) => text.trim().replace(/\\s+/g, \" \");",
"var folderName = (dir) => {",
"  const last = dir.split(/[\\\\/]+/).filter((part) => part !== \"\").pop() ?? \"\";",
"  return /^[A-Za-z]:$/.test(last) ? \"\" : last;",
"};",
"var newestFirst = (list) => list.map((item, index) => ({ item, index })).sort((a, b) => b.item.at - a.item.at || a.index - b.index).map((one) => one.item);",
"var holderOf = (item) => ({ agent: item.agent, isOwn: item.isOwn === true, isRun: item.isRun === true, parent: item.parent });",
"var identity = (agent, isOwn, project, title, dir) => JSON.stringify([isOwn ? \"\" : keyOf(agent), project, title, folderOf2(dir ?? \"\")]);",
"var isHers = (item, row) => item.isOwn === true ? row.isOwn === true : item.agent === undefined || row.isOwn !== true && keyOf(row.agent) === keyOf(item.agent);",
"var groupBoard = (model, now, repoOf, s = ZH_TW) => {",
"  const folders = new Map;",
"  const repoName = (project, dir) => {",
"    if (dir === undefined || dir === null || dir.trim() === \"\")",
"      return project;",
"    let name = folders.get(dir);",
"    if (name === undefined) {",
"      name = repoOf(dir) || folderName(dir);",
"      folders.set(dir, name);",
"    }",
